#' @param title .
#' @param showN .
#' @param showBars .
#' @param barWidth .
#' @param barLabels .
#' @param barMinLabel .
#' @param showHeat .
#' @param heatPalette .
#' @param heatLabels .
#' @param heatGap .
#' @param showWaffle .
#' @param waffleRows .
#' @param waffleCols .
#' @param waffleGap .
#' @param showPicto .
#' @param pictoRows .
#' @param pictoCols .
#' @param pictoShape .
#' @param pictoSize .
#' @param showParliament .
#' @param parlSeats .
#' @param parlRows .
#' @param parlSize .
#' @param showPie .
#' @param pieLabels .
#' @param pieMinLabel .
#' @param showDonut .
#' @param donutHole .
#' @param donutLabels .
#' @param donutMinLabel .
#' @param donutN .
#' @param showGrouped .
#' @param groupWidth .
#' @param groupLabels .
#' @param showLollipop .
#' @param lolliSize .
#' @return A results object containing:
#' \tabular{llllll}{
#'   \code{results$hint} \tab \tab \tab \tab \tab a html \cr
#'   \code{results$plot_bars} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_heat} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_waffle} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_picto} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_parliament} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_pie} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_donut} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_grouped} \tab \tab \tab \tab \tab an image \cr
#'   \code{results$plot_lollipop} \tab \tab \tab \tab \tab an image \cr
#' }
#'
#' @export
distNom <- function(
    data,
    vars,
    orientation = "horizontal",
    useDesc = FALSE,
    gridCols = 3,
    sortVars = "none",
    catSort = "levels",
    invertVars = FALSE,
    colourPalette = "jamovi",
    reversePalette = FALSE,
    plotTheme = "jamovi",
    textSize = 16,
    decimals = 0,
    legendPos = "bottom",
    legendTitle = "",
    title = "",
    showN = FALSE,
    showBars = TRUE,
    barWidth = 70,
    barLabels = TRUE,
    barMinLabel = 5,
    showHeat = FALSE,
    heatPalette = "blues",
    heatLabels = TRUE,
    heatGap = 4,
    showWaffle = FALSE,
    waffleRows = 10,
    waffleCols = 10,
    waffleGap = 10,
    showPicto = FALSE,
    pictoRows = 10,
    pictoCols = 10,
    pictoShape = "circle",
    pictoSize = 4.5,
    showParliament = FALSE,
    parlSeats = 100,
    parlRows = 4,
    parlSize = 3.2,
    showPie = FALSE,
    pieLabels = TRUE,
    pieMinLabel = 5,
    showDonut = FALSE,
    donutHole = 55,
    donutLabels = TRUE,
    donutMinLabel = 6,
    donutN = TRUE,
    showGrouped = FALSE,
    groupWidth = 85,
    groupLabels = TRUE,
    showLollipop = FALSE,
    lolliSize = 4) {

    if ( ! requireNamespace("jmvcore", quietly=TRUE))
        stop("distNom requires jmvcore to be installed (restart may be required)")

    if ( ! missing(vars)) vars <- jmvcore::resolveQuo(jmvcore::enquo(vars))
    if (missing(data))
        data <- jmvcore::marshalData(
            parent.frame(),
            `if`( ! missing(vars), vars, NULL))

    for (v in vars) if (v %in% names(data)) data[[v]] <- as.factor(data[[v]])

    options <- distNomOptions$new(
        vars = vars,
        orientation = orientation,
        useDesc = useDesc,
        gridCols = gridCols,
        sortVars = sortVars,
        catSort = catSort,
        invertVars = invertVars,
        colourPalette = colourPalette,
        reversePalette = reversePalette,
        plotTheme = plotTheme,
        textSize = textSize,
        decimals = decimals,
        legendPos = legendPos,
        legendTitle = legendTitle,
        title = title,
        showN = showN,
        showBars = showBars,
        barWidth = barWidth,
        barLabels = barLabels,
        barMinLabel = barMinLabel,
        showHeat = showHeat,
        heatPalette = heatPalette,
        heatLabels = heatLabels,
        heatGap = heatGap,
        showWaffle = showWaffle,
        waffleRows = waffleRows,
        waffleCols = waffleCols,
        waffleGap = waffleGap,
        showPicto = showPicto,
        pictoRows = pictoRows,
        pictoCols = pictoCols,
        pictoShape = pictoShape,
        pictoSize = pictoSize,
        showParliament = showParliament,
        parlSeats = parlSeats,
        parlRows = parlRows,
        parlSize = parlSize,
        showPie = showPie,
        pieLabels = pieLabels,
        pieMinLabel = pieMinLabel,
        showDonut = showDonut,
        donutHole = donutHole,
        donutLabels = donutLabels,
        donutMinLabel = donutMinLabel,
        donutN = donutN,
        showGrouped = showGrouped,
        groupWidth = groupWidth,
        groupLabels = groupLabels,
        showLollipop = showLollipop,
        lolliSize = lolliSize)

    analysis <- distNomClass$new(
        options = options,
        data = data)

    analysis$run()

    analysis$results
}

